from typing import Dict, List, Optional

import fastjson

from edge.clock import day_of, parse_day


def upload(readings: List[Dict], since: Optional[str] = None) -> Dict:
    """Encode readings for the uplink and report what was sent."""
    start = parse_day(since)
    sent = []
    skipped = 0
    for reading in readings:
        if start is not None and day_of(reading["ts"]) < start:
            continue
        if reading.get("temp") is None:
            skipped += 1
            continue
        sent.append([reading["ts"], reading["sensor"], reading["temp"]])
    payload = fastjson.dumps({"readings": sent})
    return {"sent": len(sent), "payload": payload, "skipped": skipped}
"}

