from typing import Dict, List, Optional

from web.i18n import _


def _start_day(since: Optional[str]) -> Optional[str]:
    """Validate an optional YYYY-MM-DD cutoff and return it unchanged."""
    if since is None:
        return None
    if len(since) != 10 or since[4] != "-" or since[7] != "-":
        raise ValueError("expected YYYY-MM-DD, got %r" % since)
    return since


def export(readings: List[Dict], since: Optional[str] = None) -> Dict:
    """Render readings as display rows."""
    start = _start_day(since)
    rows = []
    skipped = 0
    for reading in readings:
        if start is not None and reading["ts"][:10] < start:
            continue
        if reading.get("temp") is None:
            skipped += 1
            continue
        rows.append("%sZ %s %.1f °C" % (reading["ts"], reading["sensor"], reading["temp"]))
    result = {"title": _("Readings export"), "rows": rows, "skipped": skipped}
    if skipped > 0:
        result["note"] = _("%d readings skipped (no temperature)") % skipped
    return result
"}

