{"file_path": "tests/test_web.py", "content": "import unittest

from web import export, i18n


class TestExport(unittest.TestCase):
    def test_rows(self):
        out = export.export([{"ts": "2026-10-01T09:00:00", "sensor": "a1", "temp": 20.0}])
        self.assertEqual(out["rows"], ["2026-10-01T09:00:00Z a1 20.0 °C"])
        self.assertEqual(out["skipped"], 0)
        self.assertNotIn("note", out)

    def test_missing_temperature_is_skipped_with_note(self):
        out = export.export(
            [
                {"ts": "2026-10-01T09:00:00", "sensor": "a1", "temp": 20.0},
                {"ts": "2026-10-01T10:00:00", "sensor": "a2", "temp": None},
            ]
        )
        self.assertEqual(out["rows"], ["2026-10-01T09:00:00Z a1 20.0 °C"])
        self.assertEqual(out["skipped"], 1)
        self.assertEqual(out["note"], "1 readings skipped (no temperature)")
        self.assertIn("%d readings skipped (no temperature)", i18n.SEEN)

    def test_note_is_absent_when_nothing_was_skipped(self):
        out = export.export([{"ts": "2026-10-01T09:00:00", "sensor": "a1", "temp": 20.0}])
        self.assertNotIn("note", out)

    def test_since_drops_earlier_readings_without_counting_them_skipped(self):
        out = export.export(
            [
                {"ts": "2026-09-30T23:59:59", "sensor": "a1", "temp": None},
                {"ts": "2026-10-01T00:00:00", "sensor": "a2", "temp": 21.0},
                {"ts": "2026-10-02T09:00:00", "sensor": "a3", "temp": 22.0},
            ],
            since="2026-10-01",
        )
        self.assertEqual(out["rows"], [
            "2026-10-01T00:00:00Z a2 21.0 °C",
            "2026-10-02T09:00:00Z a3 22.0 °C",
        ])
        self.assertEqual(out["skipped"], 0)
        self.assertNotIn("note", out)

    def test_since_keeps_skipped_readings_on_or_after_cutoff(self):
        out = export.export(
            [
                {"ts": "2026-10-01T09:00:00", "sensor": "a1", "temp": None},
                {"ts": "2026-10-02T09:00:00", "sensor": "a2", "temp": 22.0},
            ],
            since="2026-10-01",
        )
        self.assertEqual(out["skipped"], 1)
        self.assertEqual(out["note"], "1 readings skipped (no temperature)")

    def test_invalid_since_is_rejected(self):
        with self.assertRaises(ValueError):
            export.export([], since="01/10/2026")
"}

